var t=[{title:`Waar het geluid vandaan komt`,text:`Herhaalde voetlandingen, touwtjespringen, burpees, zware landingen, rollende apparatuur en gevallen dumbbells voeren geluid door een gebouw. Dunne vloeren kunnen een kleine impact luid laten klinken. Een routine die in een sportschool op de begane grond stil lijkt, kan mensen onder een bovenwoning storen.`},{title:`Stillere alternatieven`,text:`Vervang jumping jacks door zijwaartse stappen, jump squats door beheerste squats, op de plaats rennen door marcheren en burpees met hoge impact door versies met een stap naar achteren. Schaduwboksen, stevig wandelen, stationair fietsen en beheerste step-ups kunnen je ademhaling en hartslag verhogen zonder herhaalde harde landingen.`},{title:`Verbeter de opstelling`,text:`Train op een vrije, antislipvloer. Een oefenmat kan wat geluid dempen en de vloer beschermen, maar kan trillingen door de constructie niet tegenhouden. Zet gewichten bewust neer en stapel geen losse uitrusting. Controleer of een steponderstel of bank bij elke herhaling schommelt en bonkt.`},{title:`Intensiteit zonder impact`,text:`Hoe zwaar cardio voelt, hangt af van je inspanning, en springen is maar één manier om die te verhogen. Langere intervallen, kortere rust waarbij je nog kunt herstellen of continue beweging met lage impact bouwen allemaal conditie op. Bij krachttraining kunnen langzame beheerste lifts en pauzes zwaar werk zijn en stil blijven, dus je hoeft niet te haasten om een training zwaarder te laten voelen.`},{title:`TrainUp gebruiken`,text:`In Profiel zijn of springen mag en hoeveel geluid mag twee aparte instellingen. Beperk je beide, dan laat het schema sprongen, touwtjespringen en andere stampende oefeningen weg en train je met stillere oefeningen toch naar je doel. Een mat alleen maakt een sprongoefening niet stil.`}];var a=[{label:`Beweegaanbevelingen van de CDC voor volwassenen`,url:`https://www.cdc.gov/physical-activity-basics/guidelines/adults.html`},{label:`CDC: de intensiteit van activiteit meten en de praattest`,url:`https://www.cdc.gov/physicalactivity/basics/measuring/index.html`},{label:`ACE-oefeningenbibliotheek`,url:`https://www.acefitness.org/resources/everyone/exercise-library/`}];var i={sections:t,sources:a};export{i as default,t as sections,a as sources};